#!/bin/sh
export NODE_RANK=$SLURM_PROCID
export NNODES=$SLURM_NNODES
export GPUS_PER_NODE=$SLURM_GPUS_ON_NODE

echo "Hi from $(hostname)!"

ulimit -n 131072;


export ROOT_DIR=$ROOT_DIR
export PYTHONPATH=${ROOT_DIR}:${ROOT_DIR}/contrib/composer:${ROOT_DIR}/contrib/streaming:${ROOT_DIR}/contrib/gigafsdp

LOG_DIR_NAME=${LOG_DIR_NAME:-logs_tokenization}
LOGDIR="${ROOT_DIR}/${LOG_DIR_NAME}/$SLURM_JOB_ID"

mkdir -p $LOGDIR
echo $(env) > $LOGDIR/$SLURM_PROCID.env

EXECUTOR_SCRIPT_PATH=$EXECUTOR_SCRIPT_PATH
TOKENIZATION_SCRIPT_PATH=$TOKENIZATION_SCRIPT_PATH
TOKENIZER_PATH=$TOKENIZER_PATH
TASK_FILE_PATH=$TASK_FILE_PATH
MAX_TOKENIZED_LEN=$MAX_TOKENIZED_LEN
EXECUTOR=$SLURM_PROCID
N_PROC=$N_PROC
SCRIPT_ADDITIONAL_PARAMS=$SCRIPT_ADDITIONAL_PARAMS

TOKENIZE_EXECUTOR_LAUNCH_PARAMS=""
if [ ! -z "$SCRIPT_ADDITIONAL_PARAMS" ]; then
  TOKENIZE_EXECUTOR_LAUNCH_PARAMS="$TOKENIZE_EXECUTOR_LAUNCH_PARAMS --script-additional-params $SCRIPT_ADDITIONAL_PARAMS"
fi

# fix number of processes
export TORCHINDUCTOR_COMPILE_THREADS=1
export HOME="/home/user/"

{

    python $EXECUTOR_SCRIPT_PATH $TOKENIZE_EXECUTOR_LAUNCH_PARAMS \
	--script $TOKENIZATION_SCRIPT_PATH \
	--executor $EXECUTOR \
	--task-file $TASK_FILE_PATH \
	--tokenizer $TOKENIZER_PATH \
	--max-tokenized-len $MAX_TOKENIZED_LEN \
	--n-proc $N_PROC
} > "$LOGDIR/log_${SLURM_PROCID}.txt" 2>&1

exit_code=$?

exit $exit_code
